def max_value_on_paths(N: int, grid_values: list) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.
    Each cell's value can be collected at most once, even if both paths pass through it.
    """
    # Build grid
    grid = [[0] * N for _ in range(N)]
    for x, y, v in grid_values:
        if x == 0 and y == 0 and v == 0:
            break
        grid[x - 1][y - 1] = v

    # Edge case: single cell
    if N == 1:
        return grid[0][0]

    # Initialize DP arrays
    NEG_INF = -10**18
    dp_prev = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
    dp_prev[1][1] = grid[0][0]

    # Iterate over steps k = i1 + j1 = i2 + j2
    for k in range(2, 2 * N + 1):
        dp_cur = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
        i_min = max(1, k - N)
        i_max = min(N, k - 1)
        for i1 in range(i_min, i_max + 1):
            j1 = k - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(i_min, i_max + 1):
                j2 = k - i2
                if j2 < 1 or j2 > N:
                    continue
                best = NEG_INF
                # Four possible previous moves
                for di1 in (0, 1):  # 0: came from left (i1-1), 1: came from up (i1)
                    for di2 in (0, 1):
                        pi1 = i1 - di1
                        pi2 = i2 - di2
                        if pi1 < 1 or pi2 < 1:
                            continue
                        val = dp_prev[pi1][pi2]
                        if val > best:
                            best = val
                if best == NEG_INF:
                    continue
                add = 0
                if i1 == i2 and j1 == j2:
                    add = grid[i1 - 1][j1 - 1]
                else:
                    add = grid[i1 - 1][j1 - 1] + grid[i2 - 1][j2 - 1]
                dp_cur[i1][i2] = best + add
        dp_prev = dp_cur

    return dp_prev[N][N] if dp_prev[N][N] != NEG_INF else 0

def calculate_scholarship(grades: List[int], leader: str, west: str, papers: int) -> int:
    avg, class_eval = grades
    scholarship = 0
    if avg > 80 and papers > 0:
        scholarship += 8000
    if avg > 85 and class_eval > 80:
        scholarship += 4000
    if avg > 90:
        scholarship += 2000
    if avg > 85 and west == 'Y':
        scholarship += 1000
    if class_eval > 80 and leader == 'Y':
        scholarship += 850
    return scholarship

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    terms = []
    first = True
    for idx, coeff in enumerate(coeffs):
        degree = n - idx
        if coeff == 0:
            continue

        # Determine sign
        if first:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '-' if coeff < 0 else '+'

        # Absolute value of coefficient
        abs_coeff = abs(coeff)

        # Coefficient part
        if abs_coeff == 1 and degree > 0:
            coeff_part = ''
        else:
            coeff_part = str(abs_coeff)

        # Variable part
        if degree > 1:
            var_part = f'x^{degree}'
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = ''

        term = f"{sign}{coeff_part}{var_part}"
        terms.append(term)
        first = False

    if not terms:
        return '0'
    return ''.join(terms)

def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of pairs of positive integers (P, Q) such that
    gcd(P, Q) == x0 and lcm(P, Q) == y0.

    Parameters:
    x0 (int): The required greatest common divisor of the pair.
    y0 (int): The required least common multiple of the pair.

    Returns:
    int: The number of distinct ordered pairs (P, Q) satisfying the conditions.
    """
    # If y0 is not a multiple of x0, no such pair exists.
    if y0 % x0 != 0:
        return 0

    k = y0 // x0  # product of the coprime factors a and b

    # Euclidean algorithm for gcd
    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    count = 0
    limit = int(k ** 0.5)
    for a in range(1, limit + 1):
        if k % a == 0:
            b = k // a
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
    return count

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    n = len(heights)
    if n == 0:
        return 0

    # Longest increasing subsequence ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Longest decreasing subsequence starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Find maximum bitonic subsequence length
    max_bitonic = 0
    for i in range(n):
        bitonic_len = lis[i] + lds[i] - 1  # peak counted twice
        if bitonic_len > max_bitonic:
            max_bitonic = bitonic_len

    return n - max_bitonic
